<script setup lang="ts">import { MasonryItem,MasonryRoot,MasonryViewport,type MasonryColumns,type MasonryLayoutDetail } from '@fex-design/vue/primitive/masonry';import { ref } from 'vue';import { masonryItems } from './data';const configs:{title:string;columns:MasonryColumns}[]=[{title:'最小列宽',columns:{minColumnWidth:180,max:5}},{title:'容器断点',columns:[{minWidth:0,columns:1},{minWidth:480,columns:2},{minWidth:700,columns:3},{minWidth:900,columns:4}]}];const widths=ref([720,720]),counts=ref([0,0]);const layout=(index:number,value:MasonryLayoutDetail)=>{const next=[...counts.value];next[index]=value.columnCount;counts.value=next}</script>
<template><div class="grid gap-space-xl"><section v-for="(config,configIndex) in configs" :key="config.title" class="grid gap-space-sm"><div><h3 class="font-medium">{{ config.title }}</h3><p class="text-sm text-muted-foreground">容器 {{ widths[configIndex] }}px · 当前 {{ counts[configIndex]||'…' }} 列</p></div><input v-model.number="widths[configIndex]" :aria-label="`${config.title}容器宽度`" type="range" min="280" max="960"/><div class="max-w-full overflow-hidden" :style="{width:`${widths[configIndex]}px`}"><MasonryRoot :columns="config.columns" :gap="12" :on-layout-change="value=>layout(configIndex,value)"><MasonryViewport><MasonryItem v-for="(item,index) in masonryItems.slice(0,6)" :key="item.id" :item-key="item.id" :index="index"><div class="rounded-md border border-border bg-muted-background p-space-sm" :style="{height:`${item.height/3}px`}">Card {{ index+1 }}</div></MasonryItem></MasonryViewport></MasonryRoot></div></section></div></template>
